def get_teacher(db):
    user = db.query(models.User).filter(models.User.role.in_(["teacher", "admin"])).order_by(models.User.id).first()
    if not user:
        raise RuntimeError("No teacher/admin user found. Register a teacher/admin account first.")
    return user

def main():
    db = SessionLocal()
    try:
        teacher = get_teacher(db)
        print(f"Using teacher/admin user: {teacher.name} (id={teacher.id})")
        subject_map = {}
        for name, description, language in SUBJECTS:
            subject = db.query(models.Subject).filter(models.Subject.name == name).first()
            if not subject:
                subject = models.Subject(name=name, description=description, language=language)
                db.add(subject)
                db.flush()
                print(f"Created subject: {name} (id={subject.id})")
            else:
                print(f"Subject already exists: {name} (id={subject.id})")
            subject_map[name] = subject.id
        db.commit()

        lesson_map = {}
        for subject_no, title, description, content in LESSONS:
            subject_name = SUBJECTS[subject_no - 1][0]
            subject_id = subject_map[subject_name]
            lesson = db.query(models.Lesson).filter(models.Lesson.title == title).first()
            if not lesson:
                lesson = models.Lesson(title=title, description=description, content=content, language="Hindi", subject_id=subject_id, created_by=teacher.id)
                db.add(lesson)
                db.flush()
                print(f"Created lesson: {title} (id={lesson.id})")
            else:
                print(f"Lesson already exists: {title} (id={lesson.id})")
            lesson_map[title] = lesson.id
        db.commit()

        # Map the 20 lesson records to the corresponding question bank.
        for lesson_index, lesson_row in enumerate(LESSONS, start=1):
            _, title, _, _ = lesson_row
            lesson_id = lesson_map[title]
            existing_count = db.query(models.QuizQuestion).filter(models.QuizQuestion.lesson_id == lesson_id).count()
            if existing_count >= 10:
                print(f"Questions already present for: {title} ({existing_count})")
                continue
            for q in QUESTIONS[lesson_index]:
                question_text, a, b, c, d, correct, explanation = q
                db.add(models.QuizQuestion(lesson_id=lesson_id, question=question_text, option_a=a, option_b=b, option_c=c, option_d=d, correct_answer=correct, explanation=explanation))
            db.commit()
            print(f"Added {len(QUESTIONS[lesson_index])} quiz questions: {title}")

        print("\nDONE: 5 subjects, 20 lessons and up to 200 quiz questions are ready.")
        print("Random quiz endpoint will select 5 questions from each lesson's question bank.")
    finally:
        db.close()

if __name__ == "__main__":
    main()